/** Select the low-bitrate rendition generated by the video worker when enabled. */
export function getFeedVideoUrl(url: string | null | undefined, dataSaver: boolean): string | null {
  if (!url) return null;
  if (!dataSaver || !url.endsWith('/master.m3u8')) return url;
  return url.replace(/\/master\.m3u8$/, '/stream_0.m3u8');
}
